#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <algorithm>
bool valid(const std::string&s){if(s.empty()||s.size()>12)return false;for(char c:s)if(c<'a'||c>'z')return false;return true;}
int main(){int n;if(!(std::cin>>n)||n<0||n>64){std::cout<<"invalid\n";return 0;}
 std::unordered_map<std::string,int>counts;
 for(int i=0;i<n;++i){std::string word;if(!(std::cin>>word)||!valid(word)){std::cout<<"invalid\n";return 0;}++counts[word];}
 std::cin>>std::ws;if(!std::cin.eof()){std::cout<<"invalid\n";return 0;}
 std::vector<std::pair<std::string,int>>report(counts.begin(),counts.end());
 std::sort(report.begin(),report.end(),[](const auto&a,const auto&b){return a.first<b.first;});
 if(report.empty())std::cout<<"empty\n";
 else for(const auto&entry:report)std::cout<<entry.first<<' '<<entry.second<<'\n';
}

